package org.mockito.internal.matchers;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.hamcrest.Description;
import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentMatcher;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.verify;

public class Same_describeTo_TriageGen0Test {



    @Test
    public void testDescribeToWithComplexObject() {
        // Arrange
        // Testing with a custom object to ensure toString() is handled correctly
        class CustomObject {
            @Override
            public String toString() {
                return "CustomObj@123";
            }
        }
        CustomObject wanted = new CustomObject();
        Same same = new Same(wanted);
        Description description = Mockito.mock(Description.class);

        // Act
        same.describeTo(description);

        // Assert
        verify(description).appendText("same(");
        verify(description).appendText("CustomObj@123");
        verify(description).appendText(")");
    }
}
